import{access,readFile,writeFile}from'node:fs/promises';const root=process.env.AGENT_MCP_BILI_PROBE_ROOT;if(!root)throw Error('OWNED_METADATA_ROOT_REQUIRED');export default{id:'agent-mcp-readonly-catalog-metadata',async setup(ctx){let stopped=false,tries=0,timer;async function check(){if(stopped||tries++>=200)return;try{await access(root+'/data/mcp-catalog-request');}catch{schedule();return;}try{const request=await readFile(root+'/data/mcp-catalog-request','utf8');if(request.length>4096)throw Error('INVALID_PUBLICATION_REQUEST');let ids;if(request.trim().startsWith('{')){const q=JSON.parse(request);if(Object.keys(q).some(k=>k!=='required_ids')||!Array.isArray(q.required_ids)||q.required_ids.length<1||q.required_ids.length>64||new Set(q.required_ids).size!==q.required_ids.length||q.required_ids.some(id=>typeof id!=='string'||!/^[a-zA-Z0-9_-]{1,256}$/.test(id)))throw Error('INVALID_PUBLICATION_REQUEST');ids=q.required_ids;}const tools=await ctx.tool.list(),ready=!ids||ids.every(id=>tools.some(t=>t.id===id));await writeFile(root+'/data/mcp-native-catalog.json',JSON.stringify({pid:process.pid,tools:tools.map(t=>({id:t.id,name:t.name})),model_requests:0,tool_execution_requested:false,...ids?{ready,required_ids:ids}:{}}),{mode:0o600});if(!ready)schedule();}catch{await writeFile(root+'/data/mcp-native-catalog.json',JSON.stringify({pid:process.pid,error:'READONLY_CATALOG_FAILED_NO_VALUES'}),{mode:0o600});}}function schedule(){timer=setTimeout(check,100);timer.unref();}schedule();return()=>{stopped=true;clearTimeout(timer);};}};
